import axios from 'axios';
import { getBffProject } from '@mairie360/bff-project-openapi/endpoints/bffProject';

/**
 * Axios instance of the BFF_Project client generated by orval. Like `coreClient`, it carries no base URL: BFF_Project's
 * URL is read from `PROJECT_BFF_URL` (+ optional `PROJECT_BFF_PORT`) by `asCaller('PROJECT_BFF', req)` of
 * `@mairie360/bffs-lib` on every call (503 when it is missing). Only the administration page needs it, so the entry
 * point does not refuse to start without it.
 */
export const projectBffClient = axios.create({
    timeout: 5000,
    headers: {
        'Content-Type': 'application/json',
    },
});

/** Client generated from the BFF_Project OpenAPI contract. */
export const projectBff = getBffProject(projectBffClient);
